func (g *MoEGPU) build() error {
	// Seven bindings against the rest of the vertical's five: the quantised
	// bank at binding 5, and the same buffers again at binding 6 as sixteen-
	// byte words, because the unpack issues half as many loads through it.
	// Only this block's shaders declare either, and the router's plain GEMM
	// arm declares neither — a descriptor set may have bindings its shader
	// never names, which is what lets one sequence mix them.
	//
	// The last two bindings are **arrays** of moeMaxBanks descriptors, one a
	// layer, so the bindings are 5 + 2*48 + 1 = 102 buffers (L6a).
	//
	// **Binding 7 is the halves arena again, as sixteen-byte words** (P11):
	// the grouped GEMM's gathered A operand, eight halves a load instead of
	// one. The load addresses it by `uvec4` index, so the two offsets it
	// divides are the row stride and the arena base, and both have to be
	// whole loads — `lda` is `NEmbd + gemmPad` and every `halloc` rounds to
	// 64 elements, so they are, and this says so rather than trusting it.
	if g.lda%moeAVec != 0 || int(g.hXn)%moeAVec != 0 {
		return fmt.Errorf("llm: the gathered operand loads %d halves at a time; lda %d and xn at %d are not whole loads",
			moeAVec, g.lda, g.hXn)
	}
	// **And a K-quant block's header is one sixteen-byte load** (P12): the
	// unpack reads `d`, `dmin` and the twelve scale bytes as a single `uvec4`
	// rather than four dwords, which needs every Q4_K and Q5_K block to be
	// sixteen-byte aligned. A row's length and a block's are multiples of 16
	// by `moeRowBytes`, so what is left to check is where each region starts.
	for i, w := range g.layers {
		for _, r := range [...]struct {
			off uint32
			f   moeFmt
		}{{w.gate, w.gateFmt}, {w.up, w.upFmt}, {w.down, w.downFmt},
			{w.shGate, w.shGateFmt}, {w.shUp, w.shUpFmt}, {w.shDown, w.shDownFmt}} {
			if (r.f == fmtQ4K || r.f == fmtQ5K) && r.off%16 != 0 {
				return fmt.Errorf("llm: layer %d has a %s bank at byte %d, and the unpack reads its block header as a uvec4",
					i, r.f, r.off)
			}
		}
	}
	banks := g.bankSet()
	bufs := append([]*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.bank, g.abuf}, banks...)
	bufs = append(bufs, banks...)
	bufs = append(bufs, g.hbuf)
	counts := []uint32{1, 1, 1, 1, 1, moeMaxBanks, moeMaxBanks, 1}
	pcSize := uint32(unsafe.Sizeof(push{}))
	for name, spirv := range map[string][]byte{
		"route":   shaders.LLMMoERoute,
		"perm":    shaders.LLMMoEPerm,
		"combine": shaders.LLMMoECombine,
	} {
		if err := g.pipeline(name, spirv, vk.PipelineSpec{Buffers: bufs, Counts: counts, PushConstantSize: pcSize}); err != nil {
			return err
		}
	}
	feat := g.dev.Features()
	sgs, err := g.dev.Physical().SubgroupSizeControl()
	if err != nil {
		return fmt.Errorf("llm: subgroup size control: %w", err)
	}
	if !feat.SubgroupSizeControl || !sgs.Supported || sgs.MaxSubgroupSize < moeWave {
		return fmt.Errorf("llm: the grouped GEMM needs a pinned %d-wide subgroup", moeWave)
	}
	spec := vk.PipelineSpec{Buffers: bufs, Counts: counts, PushConstantSize: pcSize, RequiredSubgroupSize: moeWave}
	if sgs.MaxComputeWorkgroupSubgroups < 4 {
		return fmt.Errorf("llm: the widest rung needs four %d-wide subgroups a workgroup, this device allows %d",
			moeWave, sgs.MaxComputeWorkgroupSubgroups)
	}
	// One module, one pipeline per row count (P5b): `ROWS` is a
	// specialization constant in llm_moe_gemv.comp and llm_moe_router.comp,
	// so the seventy-odd `.spv` of these two families do not double. The
	// grouped GEMM below takes its row block from its own name and needs
	// none of this.
	override, overrideWave, err := moeSPVOverride()
	if err != nil {
		return err
	}
	for fi, fam := range []map[string][]byte{moeSPIRV, moeRouterSPIRV} {
		for name, spirv := range fam {
			wave := uint32(moeWave)
			if o, ok := override[name]; ok && fi == 0 {
				spirv, wave = o, overrideWave
			}
			for rows := 1; rows <= GEMVMaxRows; rows++ {
				rspec := spec
				rspec.RequiredSubgroupSize = wave
				rspec.SpecConstants = gemvSpec(rows)
				if err := g.pipeline(gemvRowName(name, rows), spirv, rspec); err != nil {
					return err
				}
			}
		}
	}
	for _, v := range gemmVariants {
		if err := g.pipeline(string(v.name), v.spirv, spec); err != nil {
			return err
		}
	}
	return nil
}

// moeSPVOverride is `LLM_MOE_SPV` (KERNELS.md G5): a build of the grouped
// GEMM loaded from disk in place of the embedded one, `up_q4k_m4=path.spv`,
// comma-separated, with `LLM_MOE_SPV_WAVE` the wave those builds were
// compiled for (64 unless said). It is this kernel's `H3_GEMM_SPV`: a
// screening knob for the ladder and the record, never the served path, and a
// build that is wrong by construction is still timed.
func moeSPVOverride() (map[string][]byte, uint32, error) {
	spec := os.Getenv("LLM_MOE_SPV")
	wave := uint32(moeWave)
	if spec == "" {
		return nil, wave, nil
	}
	out := map[string][]byte{}
	for _, kv := range strings.Split(spec, ",") {
		name, path, ok := strings.Cut(kv, "=")
		if !ok {
			return nil, 0, fmt.Errorf("llm: LLM_MOE_SPV entry %q is not name=path", kv)
		}
		if _, known := moeSPIRV[name]; !known {
			return nil, 0, fmt.Errorf("llm: LLM_MOE_SPV names %q, which is not a grouped GEMM build", name)
		}
		b, err := os.ReadFile(path)
		if err != nil {
