// chunk split sees at once, because the graph's arena holds a 480-token
// prefill instead.
func moeExpertPipe(mode string, f moeFmt, k MoEKernel, rows int) string {
	name := fmt.Sprintf("%s_%s_%s", mode, f, k)
	if MoEIsGemv(k) {
		return gemvRowName(name, rows)
	}
	return name
}

