	}
	if lw.shUpFmt != lw.upFmt {
		parts = append(parts, "up_shexp="+planName[lw.upFmt])
	}
	if lw.shDownFmt != lw.downFmt {
		parts = append(parts, "down_shexp="+planName[lw.downFmt])
	}
