	if up, down := g.foldShared(lw); !up || !down {
		t.Fatalf("restaged as %s/%s/%s against routed %s/%s/%s, the fold is up %v down %v",
			lw.shGateFmt, lw.shUpFmt, lw.shDownFmt, lw.gateFmt, lw.upFmt, lw.downFmt, up, down)
	}

