	run := func(first, rows int, fold bool) []float32 {
		t.Helper()
		if err := g.Upload(in[first*c.NEmbd:(first+rows)*c.NEmbd], rows); err != nil {
			t.Fatal(err)
		}
		g.SetSharedFold(fold)
		if err := g.Run(0); err != nil {
			t.Fatal(err)
		}
